import { Rpc } from "@effect/rpc"
import { Schema } from "effect"
import { replaySafe } from "../transport/recovery"
import { ServableModelsUnavailable } from "../errors"
import { optional } from "../schemas/codec"
import { MessageId, SessionId } from "../schemas/identifier"
import { ChatBusy, ChatNotFound, ChatPage, ChatStorageFailed, ChatUpdate, InvalidChatRequest } from "../schemas/chat"
import { ResponseReasoningEffort } from "../schemas/session-event"
import { ServingModelId } from "../schemas/serving-usage"

// The chat commands and queries (spec section 11). Every ID is generated by the client, so a
// replayed command finds its own earlier effect and does nothing. Only `StartChat` creates a chat;
// a start replayed after its chat was removed recreates it with that first message (spec section 11).

// What may be requested. These limits are command policy: stored events constrain structure only
// (spec rule 6), so a limit can change without making any stored event undecodable.
const range = (min: number, max: number) => Schema.Number.pipe(Schema.finite(), Schema.between(min, max))
const positiveUpTo = (max: number) =>
  Schema.Number.pipe(Schema.finite(), Schema.greaterThan(0), Schema.lessThanOrEqualTo(max))

export const RequestedResponseSettings = Schema.Struct({
  systemPrompt: Schema.String.pipe(Schema.maxLength(65_536)),
  temperature: optional(range(0, 2)),
  maxOutputTokens: optional(Schema.Number.pipe(Schema.int(), Schema.between(1, 2_000_000))),
  topP: optional(positiveUpTo(1)),
  topK: optional(Schema.Number.pipe(Schema.int(), Schema.between(0, 1 << 24))),
  minP: optional(range(0, 1)),
  repetitionPenalty: optional(positiveUpTo(100)),
  presencePenalty: optional(range(-2, 2)),
  frequencyPenalty: optional(range(-2, 2)),
  seed: optional(Schema.Number.pipe(Schema.int(), Schema.between(0, 0xffffffff))),
  stop: Schema.Array(Schema.String.pipe(Schema.minLength(1), Schema.maxLength(1024))).pipe(Schema.maxItems(16)),
})
export type RequestedResponseSettings = typeof RequestedResponseSettings.Type

// IDs are any non-empty string when stored; what may be requested is bounded.
const chatId = SessionId.pipe(Schema.maxLength(128))
const messageId = MessageId.pipe(Schema.maxLength(128))

/** A response wanted from a model, as the client's draft configures it. */
const response = {
  responseId: messageId,
  model: ServingModelId.pipe(Schema.maxLength(1024)),
  reasoningEffort: optional(ResponseReasoningEffort.pipe(Schema.maxLength(32))),
  settings: RequestedResponseSettings,
}

/** A payload's IDs each name a different message: one ID never names two. */
const distinct = (ids: ReadonlyArray<MessageId>) => new Set(ids).size === ids.length || "A request's IDs must differ."

/** A message and the response it asks for: the first of a new chat, or the next of an existing one. */
export const ChatMessagePayload = Schema.Struct({
  chatId,
  messageId,
  text: Schema.String.pipe(
    Schema.maxLength(1_048_576),
    Schema.filter((text) => text.trim().length > 0 || "Enter a message first.")
  ),
  ...response,
}).pipe(Schema.filter((payload) => distinct([payload.messageId, payload.responseId])))
export type ChatMessagePayload = typeof ChatMessagePayload.Type

export const ChatRetryPayload = Schema.Struct({
  chatId,
  /** The chat's latest response, which this one replaces. */
  replaces: messageId,
  ...response,
}).pipe(Schema.filter((payload) => distinct([payload.replaces, payload.responseId])))
export type ChatRetryPayload = typeof ChatRetryPayload.Type

/**
 * Renames from the title the client saw. A rename to the current title succeeds without effect, so
 * a replay of one that took effect does nothing; one from any other title fails as `title_changed`,
 * so a rename against a stale title is never silently lost. A replay after the title was changed
 * away and back to `from` (A-B-A) finds `from` current and applies again.
 */
export const ChatRenamePayload = Schema.Struct({
  chatId,
  from: Schema.String.pipe(Schema.maxLength(200)),
  title: Schema.String.pipe(Schema.minLength(1), Schema.maxLength(200)),
})
export type ChatRenamePayload = typeof ChatRenamePayload.Type

/** Names the response, so a replay can never stop a later one. */
export const ChatStopPayload = Schema.Struct({ chatId, responseId: messageId })
export type ChatStopPayload = typeof ChatStopPayload.Type

export const ChatListPayload = Schema.Struct({
  offset: Schema.NonNegativeInt,
  limit: Schema.Number.pipe(Schema.int(), Schema.between(1, 100)),
})
export type ChatListPayload = typeof ChatListPayload.Type

const chat = Schema.Struct({ chatId })

export const Chat = {
  list: Rpc.make("ListChats", {
    payload: ChatListPayload,
    success: ChatPage,
    error: ChatStorageFailed,
  }).pipe(replaySafe),
  /** Starts a new chat with its first message. A `chatId` already in use by another start is rejected. */
  start: Rpc.make("StartChat", {
    payload: ChatMessagePayload,
    success: Schema.Void,
    error: Schema.Union(InvalidChatRequest, ServableModelsUnavailable, ChatStorageFailed),
  }).pipe(replaySafe),
  send: Rpc.make("SendChatMessage", {
    payload: ChatMessagePayload,
    success: Schema.Void,
    error: Schema.Union(ChatNotFound, ChatBusy, InvalidChatRequest, ServableModelsUnavailable, ChatStorageFailed),
  }).pipe(replaySafe),
  retry: Rpc.make("RetryChatResponse", {
    payload: ChatRetryPayload,
    success: Schema.Void,
    error: Schema.Union(ChatNotFound, ChatBusy, InvalidChatRequest, ServableModelsUnavailable, ChatStorageFailed),
  }).pipe(replaySafe),
  /** Renaming to the current title observes nothing; renaming from a title that is no longer current fails. */
  rename: Rpc.make("RenameChat", {
    payload: ChatRenamePayload,
    success: Schema.Void,
    error: Schema.Union(ChatNotFound, InvalidChatRequest, ChatStorageFailed),
  }).pipe(replaySafe),
  /** Stopping a response that has already ended does nothing. */
  stop: Rpc.make("StopChatResponse", {
    payload: ChatStopPayload,
    success: Schema.Void,
    error: Schema.Union(ChatNotFound, InvalidChatRequest, ChatStorageFailed),
  }).pipe(replaySafe),
  /** Removing a chat that does not exist does nothing. */
  remove: Rpc.make("RemoveChat", {
    payload: chat,
    success: Schema.Void,
    error: ChatStorageFailed,
  }).pipe(replaySafe),
  /** The chat as it is, then each settlement's changes to it and its running response, until it is removed. */
  watch: Rpc.make("WatchChat", {
    payload: chat,
    success: ChatUpdate,
    error: Schema.Union(ChatNotFound, ChatStorageFailed),
    stream: true,
  }),
}
